#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_blackLevel;
uniform float amzp_softness;
uniform float amzp_featherPx;
uniform float amzp_cleanupPx;
uniform float amzp_edgeGamma;
uniform float amzp_preserveLuma;
uniform float amzp_previewMatte;
uniform float amzp_quality;


        float3 toLinear(float3 c){ return pow(max(c, 0.0), float3(2.2)); }
        float3 toSRGB(float3 c){ return pow(max(c, 0.0), float3(1.0/2.2)); }


        float4 sampleImg(AC_ImageInfo img, float2 uv){ return amzTexture(img.texture, uv); }

        float max3(float3 v){ return max(v.r, max(v.g, v.b)); }

        float getBaseAlpha(float3 srgb, float thr, float soft, float gamma){
            float m = max3(srgb);
            float a = smoothstep(thr, thr + soft, m);
            a = pow(clamp(a, 0.0, 1.0), gamma);
            return a;
        }

        float featherAlpha(AC_ImageInfo img, float2 uv, float baseA, float2 px, float feather){
            if (feather <= 0.0001) return baseA;
            float f = clamp(feather, 0.0, 10.0);
            float2 off = px * f;

            float3 cC = sampleImg(img, uv).rgb;
            float3 cL = sampleImg(img, uv - float2(off.x, 0.0)).rgb;
            float3 cR = sampleImg(img, uv + float2(off.x, 0.0)).rgb;
            float3 cT = sampleImg(img, uv - float2(0.0, off.y)).rgb;
            float3 cB = sampleImg(img, uv + float2(0.0, off.y)).rgb;
            float aC = max3(cC);
            float aL = max3(cL);
            float aR = max3(cR);
            float aT = max3(cT);
            float aB = max3(cB);
            float avg = (aC*0.4 + (aL+aR+aT+aB)*0.15);
            return mix(baseA, avg, 0.75);
        }

        float cleanupAlpha(AC_ImageInfo img, float2 uv, float2 px, float pixels){
            float p = abs(pixels);
            if (p < 0.001) return max3(sampleImg(img, uv).rgb);
            float2 off = px * p;
            float aC = max3(sampleImg(img, uv).rgb);
            float aL = max3(sampleImg(img, uv - float2(off.x, 0.0)).rgb);
            float aR = max3(sampleImg(img, uv + float2(off.x, 0.0)).rgb);
            float aT = max3(sampleImg(img, uv - float2(0.0, off.y)).rgb);
            float aB = max3(sampleImg(img, uv + float2(0.0, off.y)).rgb);
            float spread = max(aC, max(max(aL,aR), max(aT,aB))); 
            float choke  = min(aC, min(min(aL,aR), min(aT,aB))); 
            return (pixels >= 0.0) ? spread : choke;
        }

        void amzRender(){
            float2 image_size = getTexSize((screen.zw/1.0));
            float2 px = float2(1.0) / max(float2(image_size.x, image_size.y), 1.0);
            float2 uv = amzScreenNorm().st;
            float4 col = sampleImg(AC_ImageInfo(0,(screen.zw/1.0)), uv);

            float thr = clamp(amzp_blackLevel / 255.0, 0.0, 1.0);
            float soft = max(amzp_softness, 0.0) * 0.25; 
            float gamma = amzp_edgeGamma;


            float aBase = getBaseAlpha(col.rgb, thr, soft, gamma);


            float aFeather = featherAlpha(AC_ImageInfo(0,(screen.zw/1.0)), uv, aBase, px, amzp_featherPx);


            float aClean = cleanupAlpha(AC_ImageInfo(0,(screen.zw/1.0)), uv, px, amzp_cleanupPx);
            float mAmt = clamp(abs(amzp_cleanupPx)/10.0, 0.0, 1.0);
            float aMatte = mix(aFeather, aClean, mAmt);


            float aOut = aMatte * col.a;


            float3 unmultRGB = (amzp_preserveLuma>0.5) ? (col.rgb / max(aMatte, 1e-4)) : col.rgb;
            unmultRGB = clamp(unmultRGB, 0.0, 1.0);

            if ((amzp_previewMatte>0.5)) {
                amzOutput = float4(float3(aOut), aOut);
            } else {
                amzOutput = float4(unmultRGB, aOut);
            }
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

